import "server-only";
import data from "@/data/airports.json";

/**
 * Airport reference data from src/data/airports.json (OurAirports, generated by scripts/seed/airports.ts).
 * Held in memory: about 3,300 airports, so lookups and autocomplete need no database round trip.
 */

export type AirportRecord = {
  iata: string;
  name: string;
  city: string;
  countryCode: string;
  countryName: string;
  lat: number;
  lng: number;
  timeZone: string | null;
  popularity: number;
};

export type AirportSuggestion = { iata: string; name: string; city: string; countryCode: string; countryName: string };

type Tuple = [string, string, string, string, number, number, string | null, number];

let byCode: Map<string, AirportRecord> | undefined;
let all: AirportRecord[] | undefined;

export function fold(s: string) {
  return s
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function load() {
  if (all && byCode) return all;
  const countries = data.countries as Record<string, string>;
  all = (data.airports as unknown as Tuple[]).map(([iata, name, city, countryCode, lat, lng, timeZone, popularity]) => ({
    iata,
    name,
    city,
    countryCode,
    countryName: countries[countryCode] ?? countryCode,
    lat,
    lng,
    timeZone,
    popularity,
  }));
  byCode = new Map(all.map((a) => [a.iata, a]));
  return all;
}

export function getAirport(iata: string): AirportRecord | null {
  load();
  return byCode!.get(iata.toUpperCase()) ?? null;
}

/** Other airports that share a city name with this one (Goa: GOI and GOX). */
export function airportsInCity(city: string, countryCode: string) {
  const c = fold(city);
  return load().filter((a) => a.countryCode === countryCode && fold(a.city) === c);
}

/**
 * Ranks airports for a query:
 *  1. exact IATA code ("goi")
 *  2. city name starts with the query, or a word of it does ("del", "lum" for Kuala Lumpur)
 *  3. airport name or city contains the query ("kempegowda", "heathrow")
 * Within each tier the busier airport wins.
 */
export function rankAirports<T extends { iata: string; city: string; name: string; popularity: number }>(items: T[], q: string, limit = 8): T[] {
  const query = fold(q);
  if (query.length < 2) return [];
  const scored: { item: T; tier: number }[] = [];
  for (const item of items) {
    const iata = item.iata.toLowerCase();
    const city = fold(item.city);
    const name = fold(item.name);
    let tier = -1;
    if (iata === query) tier = 0;
    else if (city.startsWith(query)) tier = 1;
    else if (city.split(" ").some((w) => w.startsWith(query))) tier = 2;
    else if (name.includes(query) || city.includes(query)) tier = 3;
    if (tier >= 0) scored.push({ item, tier });
  }
  scored.sort((a, b) => a.tier - b.tier || b.item.popularity - a.item.popularity || a.item.iata.localeCompare(b.item.iata));
  return scored.slice(0, limit).map((s) => s.item);
}

export function suggestAirports(q: string, limit = 8): AirportSuggestion[] {
  return rankAirports(load(), q, limit).map(({ iata, name, city, countryCode, countryName }) => ({ iata, name, city, countryCode, countryName }));
}

export function countryName(code: string) {
  return (data.countries as Record<string, string>)[code] ?? code;
}

/** Country list for passport issuing country pickers. */
export function allCountries() {
  return Object.entries(data.countries as Record<string, string>)
    .map(([code, name]) => ({ code, name }))
    .sort((a, b) => a.name.localeCompare(b.name));
}
